<?php
require_once __DIR__.'/../includes/PublicCards.php';$slug=requestText('slug');
$r=loadPublicWork(static function($repo)use($slug){$p=$repo->findProgram($slug);if(!$p || $p['kind']!=='course')return null;$p['sessions']=$repo->sessions((int)$p['id']);return $p;});publicNotFoundStatus($r);$p=$r['data'];
startPublicPage('work',$p['title']??'교육 안내',$p['summary']??'교육프로그램 안내','work/programs/'.$slug);
if(!$p){renderUnavailableDetail($r);endPublicPage();exit;}
renderPageIntro('2026 하반기 연속강좌',$p['title'],$p['summary']);
?>
<section class="section"><div class="container"><div class="program-detail-intro"><div><span class="state-label"><?php echo publicEscape(programStateLabel($p)); ?></span><div class="plain-content"><?php echo renderPlainText($p['body']??''); ?></div><a class="arrow-link" href="#sessions">회차별 일정 보기 ↓</a></div><dl class="program-facts"><div><dt>대상</dt><dd><?php echo publicEscape($p['audience']); ?></dd></div><div><dt>참가비</dt><dd><?php echo publicEscape($p['fee']); ?></dd></div><div><dt>문의</dt><dd><a href="mailto:<?php echo publicEscape($p['contact_email']); ?>"><?php echo publicEscape($p['contact_email']); ?></a></dd></div></dl></div>
<section id="sessions" class="program-section"><div class="section-heading"><h2>회차별 일정</h2><p>회차별 참여 방식을 확인해 주세요.</p></div><div class="session-list">
<?php foreach($p['sessions'] as $s): $d=new DateTimeImmutable($s['starts_at'],new DateTimeZone('Asia/Seoul')); ?><article class="session-card"><div class="session-date"><span><?php echo (int)$s['number']; ?>회차</span><strong><?php echo $d->format('m.d'); ?></strong><time datetime="<?php echo $d->format('c'); ?>"><?php echo $d->format('Y년 n월 j일').' · '.['일요일','월요일','화요일','수요일','목요일','금요일','토요일'][(int)$d->format('w')].' '.$d->format('H:i'); ?></time></div><div><span class="state-label"><?php echo $s['mode']==='online'?'온라인':'현장 + 온라인'; ?></span><h3><?php echo publicEscape($s['title']); ?></h3><p class="session-speaker"><?php echo publicEscape($s['speaker']); ?></p><p><?php echo publicEscape($s['description']); ?></p><?php if($s['panel']): ?><p class="session-panel"><?php echo publicEscape($s['panel']); ?></p><?php endif; ?></div></article><?php endforeach; ?>
</div></section>
<section class="participation-block"><h2>참여 방식과 장소</h2><?php $hybrid=array_column(array_filter($p['sessions'],static fn($s)=>$s['mode']==='hybrid'),'number'); ?><p>온라인 참여는 회차별 안내를 확인해 주세요.<?php if($hybrid): ?> 현장 참여는 <?php echo publicEscape(implode('·',$hybrid)); ?>회차에 제공합니다.<?php endif; ?></p><?php if($hybrid && $p['venue']): ?><p><strong>현장 장소</strong> · <?php echo publicEscape($p['venue']); ?></p><?php endif; ?><p>온라인 회차에는 현장 참여를 제공하지 않습니다. 회차별 접속 안내는 실제 접수 후 운영 안내에 따라 확인해 주세요.</p>
<?php if($action=programAction($p)): ?><a class="btn-cta" href="<?php echo publicEscape($action['href']); ?>"><?php echo publicEscape($action['label']); ?> ↗</a><p class="external-note">신청 페이지(<?php echo publicEscape(externalLinkHost($action['href'])); ?>)로 이동합니다. 접수 완료 여부는 신청 페이지에서 확인해 주세요.</p><?php else: ?><p class="recruitment-note"><?php echo $p['recruitment_status']==='pending'?'회차 안내를 먼저 확인해 주세요. 접수 상태와 신청 안내를 확인한 뒤 신청 경로를 게시합니다.':'이번 접수는 종료되었습니다. 공개 가능한 활동 기록과 자료는 확인 후 안내합니다.'; ?></p><?php endif; ?>
</section><div class="program-credits"><p><strong>주최</strong> · <?php echo publicEscape($p['organizers']); ?></p><p><?php echo publicEscape($p['credit']); ?></p><img src="<?php echo publicEscape(assetUrl('assets/images/beautiful-foundation-ci.png')); ?>" alt="아름다운재단" width="524" height="126" loading="lazy"><p>문의 · <a href="mailto:<?php echo publicEscape($p['contact_email']); ?>"><?php echo publicEscape($p['contact_email']); ?></a></p></div>
</div></section>
